const ColorInput = ({ color, onChange, title, autoColors, className }) => {
  const classes = useStyles({ color, autoColors });
  // We rely on the browser behavior that clicking on an input's label is equivalent
  // to clicking the input to show a custom color picker button.
  // However, mobile Safari doesn't show the picker if we `display: none` the actual input,
  // so we use some CSS voodoo (Tailwind's `sr-only` utility) to visually hide it...
  return (
    <label className={`${classes.container} ${className}`}>
      <div title={title} className={`MuiPaper-elevation2 ${classes.input}`} />
      <input
        type="color"
        value={toHexRgb(autoColors && autoColors[0] ? autoColors[0] : color)}
        style={{
          position: 'absolute',
          width: 1,
          height: 1,
          padding: 0,
          margin: -1,
          overflow: 'hidden',
          clip: 'rect(0, 0, 0, 0)',
          whiteSpace: 'nowrap',
          borderWidth: 0,
        }}
        onChange={(evt) => onChange(evt.target.value)}
        onInput={(evt) => onChange(evt.target.value)}
      />
    </label>
  );
};
// ---- file: package/src/components/settings/ColorWidget.js ----
const ColorWidget = ({
    // ...
  return (
    <div className={`MuiPaper-elevation4 ${classes.root}`}>
      {showResetButton && (
        <MiradorMenuButton
          containerId={containerId}
          aria-label={t('resetColor')}
          onClick={() =>
            onChange({
              useAutoColors: true,
              color: pageColors.map((cs) => cs.color).filter((x) => x)[0] ?? color,
            })
          }
        >
          <ResetColorsIcon />
        </MiradorMenuButton>
      )}
      <ColorInput
        title={t('color')}
        autoColors={useAutoColors ? pageColors.map((colors) => colors.color) : undefined}
        color={color}
        onChange={(color) => {
          // Lackluster way to check if selection was canceled: The chance of users picking
          // the exact same colors as the autodetected one is extremely slim, so if we get that,
          // the user probably aborted the color picking and we don't have to update the color
          // settings.
          if (useAutoColors && color === toHexRgb(pageColors?.[0]?.color)) {
            return;
          }
          onChange({ color: color, useAutoColors: false });
        }}
        className={classes.foreground}
      />
    </div>
  );
};

